/* @autogenerated */
package net.civeira.phylax.feature.oauth.session.application;

import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.oauth.client.domain.gateway.ClientStoreGateway;
import net.civeira.phylax.feature.oauth.session.domain.SessionInfo;
import net.civeira.phylax.feature.oauth.session.domain.gateway.SessionStoreGateway;

/** Session Management session_state binds a registered RP origin to the public sid. */
@ApplicationScoped
@RequiredArgsConstructor
public class SessionStateService {
  private static final SecureRandom RANDOM = new SecureRandom();
  private final SessionStoreGateway sessions;
  private final ClientStoreGateway clients;
  private final TenantQueryRepositoryGateway tenants;

  public String create(String clientId, String redirect, String sid) {
    byte[] salt = new byte[16];
    RANDOM.nextBytes(salt);
    String encoded = Base64.getUrlEncoder().withoutPadding().encodeToString(salt);
    return digest(clientId, origin(redirect), sid, encoded) + "." + encoded;
  }

  public String check(String tenant, String cookie, String clientId, String rpOrigin,
      String sessionState) {
    if (clientId == null || rpOrigin == null || sessionState == null
        || !registeredOrigin(tenant, clientId, rpOrigin))
      return "error";
    int dot = sessionState.lastIndexOf('.');
    if (dot <= 0 || dot == sessionState.length() - 1
        || !sessionState.substring(dot + 1).matches("[A-Za-z0-9_-]{10,64}"))
      return "error";
    Optional<SessionInfo> session = sessions.loadSession(cookie).filter(si -> belongs(tenant, si))
        .filter(si -> sessions.participatingClients(cookie).contains(clientId));
    if (session.isEmpty() || session.get().getSid() == null)
      return "changed";
    String current =
        digest(clientId, rpOrigin, session.get().getSid(), sessionState.substring(dot + 1));
    return MessageDigest.isEqual(current.getBytes(StandardCharsets.US_ASCII),
        sessionState.substring(0, dot).getBytes(StandardCharsets.US_ASCII)) ? "unchanged"
            : "changed";
  }

  private boolean belongs(String tenant, SessionInfo info) {
    return tenant.equals(info.getIssuer())
        || tenants.find(TenantFilter.builder().name(tenant).build())
            .map(t -> t.getUid().equals(info.getIssuer())).orElse(false);
  }

  private boolean registeredOrigin(String tenant, String clientId, String rpOrigin) {
    try {
      URI origin = URI.create(rpOrigin);
      if (origin.getHost() == null || origin.getRawPath() != null && !origin.getRawPath().isEmpty()
          || origin.getRawQuery() != null || origin.getRawFragment() != null
          || !origin(origin.toString()).equals(rpOrigin))
        return false;
      return clients.loadPreautorized(tenant, clientId)
          .map(client -> client.getAllowedRedirectUris().stream()
              .anyMatch(redirect -> origin(redirect).equals(rpOrigin)))
          .orElse(false);
    } catch (IllegalArgumentException ex) {
      return false;
    }
  }

  private static String origin(String url) {
    URI uri = URI.create(url);
    return uri.getScheme() + "://" + uri.getRawAuthority();
  }

  private static String digest(String clientId, String origin, String sid, String salt) {
    try {
      byte[] value = MessageDigest.getInstance("SHA-256").digest(
          (clientId + " " + origin + " " + sid + " " + salt).getBytes(StandardCharsets.UTF_8));
      return Base64.getUrlEncoder().withoutPadding().encodeToString(value);
    } catch (java.security.NoSuchAlgorithmException ex) {
      throw new IllegalStateException(ex);
    }
  }
}
